test_renaming_aliases_and_supported_call_shapes_preserve_contract[import numpy as nx
def choose(matrix):
 roots, basis = nx.linalg.eig(matrix)
 selected = nx.argmax(nx.abs(roots))
 return roots[selected], basis[:, selected]
]

test_renaming_aliases_and_supported_call_shapes_preserve_contract[import numpy
def choose(matrix):
 values, vectors = numpy.linalg.eig(matrix)
 selected = numpy.argmax(numpy.abs(values))
 return values[selected], vectors[:, selected]
]

test_renaming_aliases_and_supported_call_shapes_preserve_contract[import numpy as np
def choose(matrix):
 values, vectors = np.linalg.eig(a=matrix)
 selected = np.argmax(a=np.abs(values))
 return values[selected], vectors[:, selected]
]

test_renaming_aliases_and_supported_call_shapes_preserve_contract[import numpy as np
def choose(matrix):
